}

function normalizeStatus(value) {
  return value === 'confirmed' ? 'confirmed' : 'pending'
}

const DEFAULT_FORM = {
  expense_date: new Date().toISOString().slice(0, 10),
  category: '',
  amount_krw: '',
  notes: '',
  receipt_url: '',
}

