}

function SwipeDeleteExpenseCard({ expense, categoryStyle, statusStyle, rates, onConfirm, onViewTicket, onEdit, onDelete }) {
  const [offsetX, setOffsetX] = useState(0)
  const [dragging, setDragging] = useState(false)
  const dragRef = useRef({ startX: null, startY: null, captured: false })

  const DELETE_THRESHOLD = 90
  const clamped = Math.max(-130, Math.min(0, offsetX))
  const leftPct = Math.min(1, Math.max(0, -clamped / DELETE_THRESHOLD))

  function onPointerDown(e) {
    if (e.pointerType === 'mouse' && e.button !== 0) return
    dragRef.current = { startX: e.clientX, startY: e.clientY, captured: false }
  }

  function onPointerMove(e) {
    const { startX, startY, captured } = dragRef.current
    if (startX === null) return

    const dx = e.clientX - startX
    const dy = e.clientY - startY

    if (!captured) {
      if (Math.abs(dy) > Math.abs(dx) + 6) {
        dragRef.current.startX = null
        return
      }
      if (Math.abs(dx) > 8) {
        e.currentTarget.setPointerCapture(e.pointerId)
        dragRef.current.captured = true
        setDragging(true)
      }
      return
    }

    setOffsetX(Math.min(0, dx))
  }

  function onPointerUp(e) {
    const { startX, captured } = dragRef.current
    dragRef.current = { startX: null, startY: null, captured: false }
    setDragging(false)
    if (!captured || startX === null) return

    const dx = e.clientX - startX
    setOffsetX(0)
    if (dx < -DELETE_THRESHOLD) onDelete(expense.id)
  }

  function onPointerCancel() {
    dragRef.current = { startX: null, startY: null, captured: false }
    setDragging(false)
    setOffsetX(0)
  }

  return (
    <div className="relative overflow-hidden rounded-2xl ring-1 ring-slate-100 dark:ring-zinc-700">
      <div
        className="pointer-events-none absolute inset-0 flex items-center justify-end rounded-2xl bg-red-500 px-5"
        style={{ opacity: leftPct }}
      >
        <span className="text-sm font-semibold text-white">Eliminar</span>
      </div>

      <div
        className={`relative bg-white p-4 dark:bg-zinc-900/75${!dragging ? ' transition-transform duration-200 ease-out' : ''}`}
        style={{ transform: `translateX(${clamped}px)`, touchAction: 'pan-y' }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerCancel}
      >
        <div className="flex items-start justify-between gap-3">
          <div className="flex min-w-0 flex-wrap items-center gap-1.5">
            <span className={`inline-flex min-w-0 items-center gap-1 rounded-full px-2.5 py-0.5 text-xs font-medium ${categoryStyle.pill}`}>
              <span className={`h-1.5 w-1.5 rounded-full ${categoryStyle.dot}`} />
              {expense.category}
            </span>
            <span className={`inline-flex rounded-full px-2 py-0.5 text-[11px] font-semibold ${statusStyle.pill}`}>
              {statusStyle.label}
            </span>
          </div>

          <div className="flex shrink-0 items-center gap-1">
            {normalizeStatus(expense.status) === 'pending' && (
              <button
                type="button"
                onClick={() => onConfirm(expense.id)}
                className="inline-flex h-7 items-center justify-center rounded-full bg-emerald-50 px-2 text-xs font-semibold text-emerald-700 hover:bg-emerald-100 dark:bg-emerald-950/30 dark:text-emerald-300"
                title="Confirmar gasto"
              >
                ✅
              </button>
            )}
            {expense.receipt_url && (
              <button
                type="button"
                onClick={() => onViewTicket(expense.receipt_url)}
                className="inline-flex h-7 items-center justify-center rounded-full bg-zinc-100 px-2 text-xs font-semibold text-zinc-700 hover:bg-zinc-200 dark:bg-zinc-800 dark:text-zinc-200"
                title="Ver ticket"
              >

              </button>
            )}
            <button
              type="button"
              onClick={() => onEdit(expense)}
              className="inline-flex h-7 items-center justify-center rounded-full bg-lavender-50 px-2 text-xs font-semibold text-lavender-700 hover:bg-lavender-100 dark:bg-lavender-950/30 dark:text-lavender-200"
              title="Editar gasto"
            >
              ✏️
            </button>
          </div>
        </div>

        <div className="mt-3 flex items-start justify-between gap-3">
          <div className="min-w-0 flex-1">
            {expense.notes && (
              <p className="text-sm font-medium text-slate-800 wrap-break-word dark:text-zinc-50">{expense.notes}</p>
            )}
            <p className="mt-1 text-xs text-slate-400 dark:text-zinc-400">{expense.expense_date}</p>
          </div>
          <div className="shrink-0 text-right">
            <p className="font-bold text-slate-900 dark:text-zinc-50">
              {Number(expense.amount_krw).toLocaleString('es-ES')} ₩
            </p>
            <p className="text-xs text-slate-400 dark:text-zinc-400">
              {(Number(expense.amount_krw) / rates.eur_krw).toFixed(2)} €
            </p>
          </div>
        </div>
      </div>
    </div>
  )
}

/* ─── Componente principal ─── */
export default function ExpenseManager({ rates }) {
  const [expenses, setExpenses]       = useState([])
  const [loading, setLoading]         = useState(true)
  const [saving, setSaving]           = useState(false)
  const [error, setError]             = useState('')
  const [filterStatus, setFilterStatus] = useState('pending')
  const [filterMonth, setFilterMonth] = useState('all')
  const [filterCat, setFilterCat]     = useState('all')
  const [showModal, setShowModal]     = useState(false)
  const [showReceipt, setShowReceipt] = useState(false)
  const [viewerUrl, setViewerUrl]     = useState('')
  const [editingExpense, setEditingExpense] = useState(null)
  const [updating, setUpdating] = useState(false)
  const [showEditReceipt, setShowEditReceipt] = useState(false)
  const [editForm, setEditForm] = useState({
    expense_date: '',
    category: '',
    amount_krw: '',
    notes: '',
    receipt_url: '',
    status: 'pending',
  })
  const [form, setForm]               = useState(DEFAULT_FORM)

  useEffect(() => { void fetchExpenses() }, [])

  async function fetchExpenses() {
    setLoading(true)
    const { data, error: e } = await supabase
      .from('expenses')
      .select('id, expense_date, category, amount_krw, notes, receipt_url, status, created_at')
      .order('expense_date', { ascending: false })
      .order('created_at', { ascending: false })
    if (e) { setError(e.message); setLoading(false); return }
    setExpenses((data ?? []).map((row) => ({ ...row, status: normalizeStatus(row.status) })))
    setLoading(false)
  }

  const months = useMemo(() => {
    const set = new Set(expenses.map((e) => e.expense_date.slice(0, 7)))
    return Array.from(set).sort()
  }, [expenses])

  const filtered = useMemo(() =>
    expenses.filter((e) => {
      const sOk = filterStatus === 'all' || normalizeStatus(e.status) === filterStatus
      const mOk = filterMonth === 'all' || e.expense_date.startsWith(filterMonth)
      const cOk = filterCat   === 'all' || e.category === filterCat
      return sOk && mOk && cOk
    }),
    [expenses, filterStatus, filterMonth, filterCat],
  )

  const totalKrw = filtered.reduce((acc, e) => acc + Number(e.amount_krw), 0)
  const totalEur = totalKrw / rates.eur_krw

  function handleChange(ev) {
    const { name, value } = ev.target
    setForm((p) => ({ ...p, [name]: value }))
  }

  function handleExtractData(extractedData) {
    setForm((prev) => ({
      ...prev,
      ...(extractedData.amount_krw && { amount_krw: extractedData.amount_krw.toString() }),
      ...(extractedData.expense_date && { expense_date: extractedData.expense_date }),
    }))
    setShowReceipt(false)
  }

  function handleReceiptUploaded(payload) {
    if (!payload?.url) return
    setForm((prev) => ({ ...prev, receipt_url: payload.url }))
    toast.success('Ticket adjuntado')
    vibrate(12)
  }

  function handleReceiptSummary(summary) {
    if (!summary) return
    setForm((prev) => ({
      ...prev,
      notes: prev.notes.trim() ? prev.notes : summary,
    }))
  }

  async function handleSubmit(ev) {
    ev.preventDefault()
    if (!form.notes.trim()) {
      setError('El motivo es obligatorio.')
      return
    }
    setSaving(true)
    setError('')
    const { data, error: e } = await supabase
      .from('expenses')
      .insert({
        expense_date: form.expense_date || new Date().toISOString().slice(0, 10),
        category:     form.category || 'Otros',
        amount_krw:   form.amount_krw ? Number(form.amount_krw) : 0,
        notes:        form.notes.trim(),
        receipt_url:  form.receipt_url || null,
        status:       'pending',
      })
      .select('id, expense_date, category, amount_krw, notes, receipt_url, status, created_at')
      .single()
    if (e) { setError(e.message); setSaving(false); return }
    setExpenses((p) => [data, ...p])
    setForm(DEFAULT_FORM)
    setSaving(false)
    setShowModal(false)
    setShowReceipt(false)
    toast.success('Gasto añadido')
    vibrate(18)
  }

  function openEdit(expense) {
    setEditingExpense(expense)
    setShowEditReceipt(false)
    setEditForm({
      expense_date: expense.expense_date || new Date().toISOString().slice(0, 10),
      category: expense.category || 'Otros',
      amount_krw: expense.amount_krw?.toString?.() ?? '',
      notes: expense.notes || '',
      receipt_url: expense.receipt_url || '',
      status: normalizeStatus(expense.status),
    })
    setError('')
  }

  function handleEditChange(ev) {
    const { name, value } = ev.target
    setEditForm((prev) => ({ ...prev, [name]: value }))
  }

  function handleEditReceiptUploaded(payload) {
    if (!payload?.url) return
    setEditForm((prev) => ({ ...prev, receipt_url: payload.url }))
    setShowEditReceipt(false)
  }

  function handleEditExtractData(extractedData) {
    setEditForm((prev) => ({
      ...prev,
      ...(extractedData.amount_krw && { amount_krw: extractedData.amount_krw.toString() }),
      ...(extractedData.expense_date && { expense_date: extractedData.expense_date }),
    }))
  }

  function handleEditReceiptSummary(summary) {
    if (!summary) return
    setEditForm((prev) => ({
      ...prev,
      notes: prev.notes.trim() ? prev.notes : summary,
    }))
  }

  async function handleConfirmExpense(id) {
    const { data, error: updateError } = await supabase
      .from('expenses')
      .update({ status: 'confirmed' })
      .eq('id', id)
      .select('id, expense_date, category, amount_krw, notes, receipt_url, status, created_at')
      .single()

    if (updateError) {
      setError(updateError.message)
      return
    }

    setExpenses((prev) => prev.map((row) => (row.id === id ? { ...data, status: normalizeStatus(data.status) } : row)))
    toast.success('Gasto confirmado')
    vibrate(12)
  }

  async function handleUpdateExpense(ev) {
    ev.preventDefault()
    if (!editingExpense) return

    if (!editForm.notes.trim()) {
      setError('El motivo es obligatorio.')
      return
    }

    setUpdating(true)

    const payload = {
      expense_date: editForm.expense_date || new Date().toISOString().slice(0, 10),
      category: editForm.category || 'Otros',
      amount_krw: editForm.amount_krw ? Number(editForm.amount_krw) : 0,
      notes: editForm.notes.trim(),
      receipt_url: editForm.receipt_url || null,
      status: normalizeStatus(editForm.status),
    }

    const { data, error: updateError } = await supabase
      .from('expenses')
      .update(payload)
      .eq('id', editingExpense.id)
      .select('id, expense_date, category, amount_krw, notes, receipt_url, status, created_at')
      .single()

    if (updateError) {
      setError(updateError.message)
      setUpdating(false)
      return
    }

    setExpenses((prev) => prev.map((row) => (row.id === data.id ? { ...data, status: normalizeStatus(data.status) } : row)))
    setEditingExpense(null)
    setShowEditReceipt(false)
    setUpdating(false)
    toast.success('Gasto actualizado')
    vibrate(12)
  }

  async function handleDelete(id) {
    const { error: e } = await supabase.from('expenses').delete().eq('id', id)
    if (e) { setError(e.message); return }
    setExpenses((p) => p.filter((ex) => ex.id !== id))
    toast.success('Gasto eliminado')
    vibrate(15)
  }

  function monthLabel(ym, idx) {
    const [y, m] = ym.split('-')
    const raw = new Date(Number(y), Number(m) - 1, 1).toLocaleDateString('es-ES', {
      month: 'long', year: 'numeric',
    })
    return `Mes ${idx + 1} – ${raw.charAt(0).toUpperCase() + raw.slice(1)}`
  }

  /* ══════════════════════════════════════════════════════════════
     RENDER
  ══════════════════════════════════════════════════════════════ */
  return (
    <>
      {/* ▓▓▓ MOBILE (md:hidden) ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓ */}
      <div className="space-y-3 pb-28 md:hidden">

        {/* Summary cards */}
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-2">
          <div className="rounded-2xl bg-lavender-500 p-4 text-white shadow-sm">
            <p className="text-xs font-medium opacity-75">Total KRW</p>
            <p className="mt-1 text-lg font-bold leading-tight">
              {totalKrw.toLocaleString('es-ES')} ₩
            </p>
          </div>
          <div className="rounded-2xl bg-white p-4 shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900 dark:ring-zinc-700">
            <p className="text-xs font-medium text-slate-500 dark:text-zinc-400">Total EUR</p>
            <p className="mt-1 text-lg font-bold leading-tight text-slate-900 dark:text-zinc-50">
              {totalEur.toFixed(2)} €
            </p>
          </div>
        </div>

        {/* Filter chips row */}
        <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">
          {['pending', 'confirmed', 'all'].map((status) => (
            <button
              key={status}
              onClick={() => setFilterStatus(status)}
              className={`shrink-0 rounded-xl px-3 py-2 text-xs font-medium transition ${
                filterStatus === status
                  ? 'bg-lavender-500 text-white shadow-sm'
                  : 'bg-white text-slate-600 ring-1 ring-slate-200 hover:ring-lavender-300 dark:bg-zinc-900/80 dark:text-zinc-200 dark:ring-zinc-700 dark:hover:ring-lavender-400'
              }`}
            >
              {status === 'pending' ? 'Pendientes' : status === 'confirmed' ? 'Confirmados' : 'Todos'}
            </button>
          ))}

          {/* Month selector */}
          <select
            value={filterMonth}
            onChange={(e) => setFilterMonth(e.target.value)}
            className="shrink-0 rounded-xl border border-slate-200 bg-white px-3 py-2
                       text-xs shadow-sm focus:outline-none focus:ring-2 focus:ring-lavender-300"
          >
            <option value="all">Todos los meses</option>
            {months.map((m, i) => (
              <option key={m} value={m}>{monthLabel(m, i)}</option>
            ))}
          </select>

          {/* Category chips */}
          {['all', ...CATEGORIES].map((cat) => (
            <button
              key={cat}
              onClick={() => setFilterCat(cat)}
              className={`shrink-0 rounded-xl px-3 py-2 text-xs font-medium transition
                          ${filterCat === cat
                            ? 'bg-lavender-500 text-white shadow-sm'
                            : 'bg-white text-slate-600 ring-1 ring-slate-200 hover:ring-lavender-300 dark:bg-zinc-900/80 dark:text-zinc-200 dark:ring-zinc-700 dark:hover:ring-lavender-400'}`}
            >
              {cat === 'all' ? 'Todas' : cat}
            </button>
          ))}
        </div>

        {/* Card list */}
        {loading ? (
          <div className="space-y-3">
            {[1, 2, 3].map((n) => <SkeletonCard key={n} />)}
          </div>
        ) : filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-center">
            <span className="text-6xl"></span>
            <p className="mt-4 font-semibold text-slate-700">Sin gastos</p>
            <p className="mt-1 text-sm text-slate-400">
              {filterStatus !== 'all' || filterCat !== 'all' || filterMonth !== 'all'
                ? 'Prueba a cambiar los filtros.'
                : 'Pulsa + para registrar tu primer gasto.'}
            </p>
          </div>
        ) : (
          <div className="space-y-2">
            {filtered.map((ex) => {
              const s = CAT_STYLES[ex.category] ?? CAT_STYLES.Otros
              const status = EXPENSE_STATUS[normalizeStatus(ex.status)]
              return (
                <SwipeDeleteExpenseCard
                  key={ex.id}
                  expense={ex}
                  categoryStyle={s}
                  statusStyle={status}
                  rates={rates}
                  onConfirm={handleConfirmExpense}
                  onViewTicket={setViewerUrl}
                  onEdit={openEdit}
                  onDelete={handleDelete}
                />
              )
            })}
            <p className="px-1 text-center text-[11px] text-slate-400 dark:text-zinc-500">
              Desliza cada gasto a la izquierda para eliminarlo.
            </p>
          </div>
        )}
      </div>

      {/* FAB ─ botón flotante */}
      <button
        onClick={() => { setError(''); setShowModal(true) }}
        className="fixed bottom-6 right-6 z-40 flex h-14 w-14 items-center justify-center
                   rounded-full bg-lavender-500 text-white shadow-xl
                   hover:bg-lavender-600 active:scale-95 transition-transform md:hidden"
        aria-label="Añadir gasto"
      >
        <span className="text-3xl leading-none">+</span>
      </button>

      {/* Bottom-sheet modal (mobile) */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end md:hidden">
          {/* Backdrop */}
          <div
            className="absolute inset-0 bg-black/40 backdrop-blur-sm"
            onClick={() => setShowModal(false)}
          />
          {/* Sheet */}
          <div className="relative max-h-[calc(100vh-1rem)] overflow-y-auto rounded-t-3xl bg-white px-4 pb-8 pt-5 shadow-2xl dark:bg-zinc-900 sm:px-6">
            {/* Handle bar */}
              <div className="mx-auto mb-4 h-1 w-10 rounded-full bg-slate-200 dark:bg-zinc-700" />
            <div className="mb-5 flex items-center justify-between">
              <h2 className="text-lg font-bold text-slate-900 dark:text-zinc-50">Nuevo gasto</h2>
              <button
                onClick={() => setShowModal(false)}
                className="flex h-8 w-8 items-center justify-center rounded-full
                           text-slate-400 hover:bg-slate-100 transition-colors dark:hover:bg-zinc-800 dark:hover:text-zinc-50"
              >
                ✕
              </button>
            </div>
            <AddExpenseForm
              form={form}
              onChange={handleChange}
              onSubmit={handleSubmit}
              saving={saving}
              error={error}
              rates={rates}
            />

            <div className="mt-4 border-t border-slate-200 pt-4 dark:border-zinc-700">
              {!showReceipt && (
                <button
                  type="button"
                  onClick={() => setShowReceipt(true)}
                  className="mb-3 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm
                             text-slate-700 hover:bg-slate-50 dark:border-zinc-700 dark:bg-zinc-900/80 dark:text-zinc-200 dark:hover:bg-zinc-800"
                >
                   Adjuntar o escanear ticket
                </button>
              )}

              {showReceipt && (
                <ReceiptUploader
                  onExtractData={handleExtractData}
                  onUploadSuccess={handleReceiptUploaded}
                  onSummaryGenerated={handleReceiptSummary}
                  rates={rates}
                />
              )}
            </div>
          </div>
        </div>
      )}

      {viewerUrl && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/70 p-3 sm:p-4">
          <div className="relative max-h-[90vh] w-full max-w-3xl overflow-hidden rounded-2xl bg-white dark:bg-zinc-900">
            <div className="flex items-center justify-between border-b border-slate-200 px-4 py-3 dark:border-zinc-700">
              <p className="text-sm font-medium text-slate-700 dark:text-zinc-200">Ticket adjunto</p>
              <button
                type="button"
                onClick={() => setViewerUrl('')}
                className="rounded-md px-2 py-1 text-slate-500 hover:bg-slate-100 hover:text-slate-700 dark:hover:bg-zinc-800 dark:hover:text-zinc-200"
                aria-label="Cerrar visor"
              >
                ✕
              </button>
            </div>
            {viewerUrl.toLowerCase().includes('.pdf') ? (
              <iframe src={viewerUrl} title="Ticket PDF" className="h-[75vh] w-full" />
            ) : (
              <img src={viewerUrl} alt="Ticket" className="max-h-[75vh] w-full object-contain" />
            )}
          </div>
        </div>
      )}

      {editingExpense && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/60 p-3 sm:p-4">
          <div className="max-h-[90vh] w-full max-w-md overflow-y-auto rounded-2xl bg-white p-4 shadow-2xl dark:bg-zinc-900 sm:p-5">
            <div className="mb-4 flex items-center justify-between">
              <h3 className="text-lg font-semibold text-slate-900 dark:text-zinc-50">Editar gasto</h3>
              <button
                type="button"
                onClick={() => {
                  setEditingExpense(null)
                  setShowEditReceipt(false)
                }}
                className="rounded-md px-2 py-1 text-slate-500 hover:bg-slate-100 dark:hover:bg-zinc-800 dark:hover:text-zinc-200"
                aria-label="Cerrar editor"
              >
                ✕
              </button>
            </div>

            <form onSubmit={handleUpdateExpense} className="space-y-3">
              <label className="block text-sm text-slate-700 dark:text-zinc-200">
                Fecha
                <input
                  type="date"
                  name="expense_date"
                  value={editForm.expense_date}
                  onChange={handleEditChange}
                  className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-50"
                />
              </label>

              <label className="block text-sm text-slate-700 dark:text-zinc-200">
                Categoría
                <select
                  name="category"
                  value={editForm.category}
                  onChange={handleEditChange}
                  className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-50"
                >
                  <option value="">Sin categoría (se guarda como Otros)</option>
                  {CATEGORIES.map((cat) => (
                    <option key={cat} value={cat}>{cat}</option>
                  ))}
                </select>
              </label>

              <label className="block text-sm text-slate-700 dark:text-zinc-200">
                Estado
                <select
                  name="status"
                  value={editForm.status}
                  onChange={handleEditChange}
                  className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-50"
                >
                  <option value="pending">Pendiente</option>
                  <option value="confirmed">Confirmado</option>
                </select>
              </label>

              <div className="md:hidden">
                <AmountKeypadField
                  name="amount_krw"
                  label="Cantidad (KRW)"
                  value={editForm.amount_krw}
                  onChange={handleEditChange}
                  placeholder="Opcional"
                />
              </div>

              <div className="hidden md:block">
                <label className="mb-1 block text-sm text-slate-700 dark:text-zinc-200">Cantidad (KRW)</label>
                <input
                  type="text"
                  inputMode="numeric"
                  name="amount_krw"
                  value={editForm.amount_krw}
                  onChange={handleEditChange}
                  placeholder="Opcional"
                  className="w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-50"
                />
              </div>

              <label className="block text-sm text-slate-700 dark:text-zinc-200">
                Motivo
                <input
                  type="text"
                  name="notes"
                  value={editForm.notes}
                  onChange={handleEditChange}
                  required
                  className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-50"
                />
              </label>

              <div className="space-y-2 rounded-xl border border-slate-200 p-3 dark:border-zinc-700">
                <div className="flex items-center justify-between gap-2">
                  <p className="text-sm font-medium text-slate-700 dark:text-zinc-200">Ticket</p>
                  <div className="flex items-center gap-2">
                    {editForm.receipt_url && (
                      <button
                        type="button"
                        onClick={() => setViewerUrl(editForm.receipt_url)}
                        className="rounded-lg border border-slate-300 px-2 py-1 text-xs text-slate-700 hover:bg-slate-50 dark:border-zinc-700 dark:text-zinc-200 dark:hover:bg-zinc-800"
                      >
                        Ver adjunto
                      </button>
                    )}
                    <button
                      type="button"
                      onClick={() => setShowEditReceipt((prev) => !prev)}
                      className="rounded-lg border border-slate-300 px-2 py-1 text-xs text-slate-700 hover:bg-slate-50 dark:border-zinc-700 dark:text-zinc-200 dark:hover:bg-zinc-800"
                    >
                      {showEditReceipt ? 'Ocultar' : 'Adjuntar'}
                    </button>
                  </div>
                </div>

                {editForm.receipt_url && (
                  <p className="text-xs text-emerald-600 dark:text-emerald-300">Ticket adjunto correctamente.</p>
                )}

                {showEditReceipt && (
                  <ReceiptUploader
                    onUploadSuccess={handleEditReceiptUploaded}
                    onExtractData={handleEditExtractData}
                    onSummaryGenerated={handleEditReceiptSummary}
                  />
                )}
              </div>

              <div className="flex items-center justify-end gap-2 pt-2">
                <button
                  type="button"
                  onClick={() => setEditingExpense(null)}
                  className="rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-700 hover:bg-slate-50 dark:border-zinc-700 dark:text-zinc-200 dark:hover:bg-zinc-900"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  disabled={updating}
                  className="rounded-lg bg-lavender-500 px-4 py-2 text-sm font-medium text-white hover:bg-lavender-600 disabled:opacity-50"
                >
                  {updating ? 'Guardando…' : 'Guardar cambios'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ▓▓▓ DESKTOP (hidden md:flex) ▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓ */}
      <div className="hidden md:flex gap-6 items-start">

        {/* ── Sidebar ── */}
        <aside className="w-72 shrink-0 space-y-4 md:sticky md:top-24 lg:top-[104px]">

          {/* Form panel */}
          <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700">
            <p className="mb-4 text-xs font-bold uppercase tracking-wider text-slate-400">
              Añadir gasto
            </p>
            <AddExpenseForm
              form={form}
              onChange={handleChange}
              onSubmit={handleSubmit}
              saving={saving}
              error={error}
              rates={rates}
            />

            <div className="mt-4 border-t border-slate-200 pt-4 dark:border-zinc-700">
              {!showReceipt && (
                <button
                  type="button"
                  onClick={() => setShowReceipt(true)}
                  className="mb-3 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm text-slate-700 hover:bg-slate-50 dark:border-zinc-700 dark:bg-zinc-900/80 dark:text-zinc-200 dark:hover:bg-zinc-800"
                >
                   Adjuntar o escanear ticket
                </button>
              )}

              {showReceipt && (
                <ReceiptUploader
                  onExtractData={handleExtractData}
                  onUploadSuccess={handleReceiptUploaded}
                  onSummaryGenerated={handleReceiptSummary}
                  rates={rates}
                />
              )}
            </div>
          </div>

          {/* Filter panel */}
          <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-4 dark:bg-zinc-900/80 dark:ring-zinc-700">
            <p className="text-xs font-bold uppercase tracking-wider text-slate-400 dark:text-zinc-500">Filtros</p>

            <div>
              <label className="mb-2 block text-xs font-medium text-slate-500">Estado</label>
              <div className="grid grid-cols-3 gap-2">
                {[
                  { id: 'pending', label: 'Pendientes' },
                  { id: 'confirmed', label: 'Confirmados' },
                  { id: 'all', label: 'Todos' },
                ].map((status) => (
                  <button
                    key={status.id}
                    onClick={() => setFilterStatus(status.id)}
                    className={`rounded-lg px-2 py-2 text-xs transition-colors ${
                      filterStatus === status.id
                        ? 'bg-lavender-50 font-semibold text-lavender-700 dark:bg-lavender-950/30 dark:text-lavender-200'
                        : 'text-slate-600 hover:bg-slate-50 dark:text-zinc-200 dark:hover:bg-zinc-800/70'
                    }`}
                  >
                    {status.label}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="mb-1 block text-xs font-medium text-slate-500">Mes</label>
              <select
                value={filterMonth}
                onChange={(e) => setFilterMonth(e.target.value)}
                className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-lavender-300 dark:border-zinc-700 dark:bg-zinc-900/80 dark:text-zinc-50"
              >
                <option value="all">Todos los meses</option>
                {months.map((m, i) => (
                  <option key={m} value={m}>{monthLabel(m, i)}</option>
                ))}
              </select>
            </div>

            <div>
              <label className="mb-2 block text-xs font-medium text-slate-500">Categoría</label>
              <div className="space-y-0.5">
                {['all', ...CATEGORIES].map((cat) => (
                  <button
                    key={cat}
                    onClick={() => setFilterCat(cat)}
                    className={`flex w-full items-center gap-2.5 rounded-lg px-3 py-2 text-sm
                                transition-colors text-left
                                ${filterCat === cat
                                                  ? 'bg-lavender-50 font-semibold text-lavender-700 dark:bg-lavender-950/30 dark:text-lavender-200'
                                                  : 'text-slate-600 hover:bg-slate-50 dark:text-zinc-200 dark:hover:bg-zinc-800/70'}`}
                  >
                    {cat !== 'all' && (
                      <span className={`h-2 w-2 rounded-full shrink-0
                                        ${CAT_STYLES[cat]?.dot ?? 'bg-slate-300'}`} />
                    )}
                    {cat === 'all' ? 'Todas las categorías' : cat}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Summary panel */}
          <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-3 dark:bg-zinc-900/80 dark:ring-zinc-700">
            <p className="text-xs font-bold uppercase tracking-wider text-slate-400 dark:text-zinc-500">Resumen</p>
            <div className="rounded-xl bg-lavender-500 p-4 text-white">
              <p className="text-xs font-medium opacity-75">Total KRW</p>
              <p className="mt-1 text-2xl font-bold tabular-nums">
                {totalKrw.toLocaleString('es-ES')} ₩
              </p>
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div className="rounded-xl bg-slate-50 p-3 dark:bg-zinc-800/60">
                <p className="text-xs text-slate-500 dark:text-zinc-400">Total EUR</p>
                <p className="mt-0.5 text-base font-bold text-slate-900 tabular-nums dark:text-zinc-50">
                  {totalEur.toFixed(2)} €
                </p>
              </div>
              <div className="rounded-xl bg-slate-50 p-3 dark:bg-zinc-800/60">
                <p className="text-xs text-slate-500 dark:text-zinc-400">Nº gastos</p>
                <p className="mt-0.5 text-base font-bold text-slate-900 dark:text-zinc-50">{filtered.length}</p>
              </div>
            </div>
          </div>
        </aside>

        {/* ── Table ── */}
        <section className="flex-1 min-w-0">
          <div className="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700">
            {/* Table header bar */}
            <div className="flex items-center justify-between border-b border-slate-100 px-6 py-4 dark:border-zinc-700">
              <h2 className="font-semibold text-slate-900 dark:text-zinc-50">
                Historial de gastos
                {filtered.length > 0 && (
                  <span className="ml-2 rounded-full bg-slate-100 px-2 py-0.5 text-xs font-medium text-slate-500 dark:bg-zinc-800/80 dark:text-zinc-300">
                    {filtered.length}
                  </span>
                )}
              </h2>
            </div>

            {loading ? (
              /* Loading state */
              <div className="divide-y divide-slate-50 dark:divide-zinc-800">
                {[1, 2, 3, 4, 5].map((n) => (
                  <div key={n} className="flex animate-pulse items-center gap-4 px-6 py-4">
                    <div className="h-3 w-20 rounded bg-slate-100" />
                    <div className="h-5 w-16 rounded-full bg-slate-100" />
                    <div className="h-3 flex-1 rounded bg-slate-50" />
                    <div className="h-3 w-24 rounded bg-slate-100" />
                    <div className="h-3 w-12 rounded bg-slate-50" />
                  </div>
                ))}
              </div>
            ) : filtered.length === 0 ? (
              /* Empty state */
              <div className="flex flex-col items-center justify-center py-24 text-center">
                <span className="text-6xl"></span>
                <p className="mt-4 text-base font-semibold text-slate-700">
                  Sin gastos registrados
                </p>
                <p className="mt-1 text-sm text-slate-400">
                  {filterStatus !== 'all' || filterCat !== 'all' || filterMonth !== 'all'
                    ? 'Prueba a cambiar los filtros del panel lateral.'
                    : 'Añade tu primer gasto desde el panel de la izquierda.'}
                </p>
              </div>
            ) : (
              /* Table */
              <div className="overflow-x-auto">
                <table className="w-full border-collapse text-sm">
                  <thead>
                    <tr className="border-b border-slate-100 bg-slate-50 text-left">
                      <th className="px-6 py-3 text-xs font-semibold uppercase tracking-wider text-slate-400">
                        Fecha
                      </th>
                      <th className="px-4 py-3 text-xs font-semibold uppercase tracking-wider text-slate-400">
                        Categoría
                      </th>
                      <th className="px-4 py-3 text-xs font-semibold uppercase tracking-wider text-slate-400">
                        Concepto
                      </th>
                      <th className="px-4 py-3 text-xs font-semibold uppercase tracking-wider text-slate-400">
                        Estado
                      </th>
                      <th className="px-4 py-3 text-right text-xs font-semibold uppercase tracking-wider text-slate-400">
                        KRW
                      </th>
                      <th className="px-4 py-3 text-right text-xs font-semibold uppercase tracking-wider text-slate-400">
                        EUR
                      </th>
                      <th className="w-24 px-4 py-3" />
                    </tr>
                  </thead>

                  <tbody className="divide-y divide-slate-50">
                    {filtered.map((ex) => {
                      const s = CAT_STYLES[ex.category] ?? CAT_STYLES.Otros
                      const status = EXPENSE_STATUS[normalizeStatus(ex.status)]
                      return (
                        <tr
                          key={ex.id}
                          className="group transition-colors hover:bg-slate-50 dark:hover:bg-zinc-800/70"
                        >
                          <td className="whitespace-nowrap px-6 py-3.5 text-slate-500 dark:text-zinc-400">
                            {ex.expense_date}
                          </td>
                          <td className="px-4 py-3.5">
                            <span className={`inline-flex items-center gap-1.5 rounded-full
                                             px-2.5 py-0.5 text-xs font-medium ${s.pill}`}>
                              <span className={`h-1.5 w-1.5 rounded-full ${s.dot}`} />
                              {ex.category}
                            </span>
                          </td>
                          <td className="max-w-xs truncate px-4 py-3.5 text-slate-700 dark:text-zinc-200">
                            {ex.notes || (
                              <span className="italic text-slate-300 dark:text-zinc-500">Sin detalle</span>
                            )}
                          </td>
                          <td className="px-4 py-3.5">
                            <span className={`inline-flex rounded-full px-2.5 py-0.5 text-xs font-semibold ${status.pill}`}>
                              {status.label}
                            </span>
                          </td>
                          <td className="whitespace-nowrap px-4 py-3.5 text-right font-semibold tabular-nums text-slate-900 dark:text-zinc-50">
                            {Number(ex.amount_krw).toLocaleString('es-ES')} ₩
                          </td>
                          <td className="whitespace-nowrap px-4 py-3.5 text-right tabular-nums text-slate-400 dark:text-zinc-400">
                            {(Number(ex.amount_krw) / rates.eur_krw).toFixed(2)} €
                          </td>
                          <td className="px-4 py-3.5 text-right">
                            <div className="flex items-center justify-end gap-1.5">
                              {normalizeStatus(ex.status) === 'pending' && (
                                <button
                                  type="button"
                                  onClick={() => handleConfirmExpense(ex.id)}
                                  className="rounded-lg border border-emerald-200 bg-emerald-50 px-2 py-1 text-xs font-semibold text-emerald-700 transition hover:bg-emerald-100 dark:border-emerald-900/60 dark:bg-emerald-950/30 dark:text-emerald-300"
                                  title="Confirmar gasto"
                                  aria-label="Confirmar gasto"
                                >
                                  ✅ Confirmar
                                </button>
                              )}
                              {ex.receipt_url && (
                                <button
                                  type="button"
                                  onClick={() => setViewerUrl(ex.receipt_url)}
                                   className="rounded-lg border border-zinc-200 bg-zinc-50 px-2 py-1 text-xs font-semibold text-zinc-700 transition hover:bg-zinc-100 dark:border-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-200"
                                  title="Ver ticket"
                                  aria-label="Ver ticket"
                                >
                                   Ticket
                                </button>
                              )}
                              <button
                                type="button"
                                onClick={() => openEdit(ex)}
                                  className="rounded-lg border border-lavender-200 bg-lavender-50 px-2 py-1 text-xs font-semibold text-lavender-700 transition hover:bg-lavender-100 dark:border-lavender-900/60 dark:bg-lavender-950/30 dark:text-lavender-200"
                                title="Editar"
                                aria-label="Editar"
                              >
                                ✏️ Editar
                              </button>
                              <button
                                onClick={() => handleDelete(ex.id)}
                                className="rounded-lg border border-red-200 bg-red-50 px-2 py-1 text-xs font-semibold text-red-600 transition hover:bg-red-100 dark:border-red-900/60 dark:bg-red-950/30 dark:text-red-300"
                                title="Eliminar"
                              >
                                ✕ Borrar
                              </button>
                            </div>
                          </td>
                        </tr>
                      )
                    })}
                  </tbody>

                  {/* Footer totals */}
                  <tfoot>
                    <tr className="border-t-2 border-slate-200 bg-slate-50 dark:border-zinc-700 dark:bg-zinc-800/60">
                      <td colSpan={4} className="px-6 py-3 text-xs font-semibold
                                                  uppercase tracking-wider text-slate-400 dark:text-zinc-500">
                        Total — {filtered.length}{' '}
                        {filtered.length === 1 ? 'gasto' : 'gastos'}
                      </td>
                      <td className="px-4 py-3 text-right font-bold tabular-nums text-slate-900 dark:text-zinc-50">
                        {totalKrw.toLocaleString('es-ES')} ₩
                      </td>
                      <td className="px-4 py-3 text-right font-bold tabular-nums text-slate-600 dark:text-zinc-300">
                        {totalEur.toFixed(2)} €
                      </td>
                      <td />
                    </tr>
                  </tfoot>
                </table>
              </div>
            )}
          </div>
        </section>
      </div>
    </>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { supabase } from '../supabaseClient'

const PLACE_CATEGORIES = ['Cultura', 'Cafés', 'Vistas', 'Compras', 'Restaurantes', 'Ocio', 'Otro']
const ZONES = [
  'Hongdae',
  'Anguk',
  'Insadong',
  'Myeongdong',
  'Gangnam',
  'Itaewon',
  'Dongdaemun',
  'Busan',
  'Gyeongju',
  'Otro',
]

const CAT_COLORS = {
  Cultura: 'bg-amber-100 text-amber-700',
  Cafés: 'bg-brown-100 text-yellow-800',
  Vistas: 'bg-sky-100 text-sky-700',
  Compras: 'bg-pink-100 text-pink-700',
  Restaurantes: 'bg-orange-100 text-orange-700',
  Ocio: 'bg-purple-100 text-purple-700',
  Otro: 'bg-slate-100 text-slate-700',
}

export default function PlacesToVisit() {
  const [places, setPlaces] = useState([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')

  const [filterStatus, setFilterStatus] = useState('all')
  const [filterZone, setFilterZone] = useState('all')
  const [filterCat, setFilterCat] = useState('all')

  const [form, setForm] = useState({ name: '', district: '', category: '', notes: '' })

  useEffect(() => {
    void fetchPlaces()
  }, [])

  async function fetchPlaces() {
    setLoading(true)
    const { data, error: e } = await supabase
      .from('places')
      .select('id, name, district, category, status, notes, created_at')
      .order('status', { ascending: true })
      .order('created_at', { ascending: false })
    if (e) {
      setError(e.message)
      setLoading(false)
      return
    }
    setPlaces(data ?? [])
    setLoading(false)
  }

  function handleChange(ev) {
    const { name, value } = ev.target
    setForm((p) => ({ ...p, [name]: value }))
  }

  async function handleSubmit(ev) {
    ev.preventDefault()
    if (!form.name.trim()) {
      setError('El nombre del lugar es obligatorio.')
      return
    }
    setSaving(true)
    setError('')
    const { data, error: e } = await supabase
      .from('places')
      .insert({
        name: form.name.trim(),
        city: 'Korea',
        district: form.district || null,
        category: form.category || null,
        notes: form.notes.trim() || null,
        status: 'pendiente',
      })
      .select('id, name, district, category, status, notes, created_at')
      .single()
    if (e) {
      setError(e.message)
      setSaving(false)
      return
    }
    setPlaces((p) => [data, ...p])
    setForm({ name: '', district: '', category: '', notes: '' })
    setSaving(false)
  }

  async function toggleVisited(place) {
    const newStatus = place.status === 'visitado' ? 'pendiente' : 'visitado'
    const { error: e } = await supabase
      .from('places')
      .update({ status: newStatus })
      .eq('id', place.id)
    if (e) {
      setError(e.message)
      return
    }
    setPlaces((p) => p.map((pl) => (pl.id === place.id ? { ...pl, status: newStatus } : pl)))
  }

  async function handleDelete(id) {
    const { error: e } = await supabase.from('places').delete().eq('id', id)
    if (e) {
      setError(e.message)
      return
    }
    setPlaces((p) => p.filter((pl) => pl.id !== id))
  }

  const visited = places.filter((p) => p.status === 'visitado').length

  // Dynamic filter options from actual data
  const availableZones = useMemo(
    () => [...new Set(places.map((p) => p.district).filter(Boolean))],
    [places],
  )
  const availableCats = useMemo(
    () => [...new Set(places.map((p) => p.category).filter(Boolean))],
    [places],
  )

  const filtered = places.filter((pl) => {
    const statusMatch = filterStatus === 'all' || pl.status === filterStatus
    const zoneMatch = filterZone === 'all' || pl.district === filterZone
    const catMatch = filterCat === 'all' || pl.category === filterCat
    return statusMatch && zoneMatch && catMatch
  })

  return (
    <div className="space-y-4">
      {/* Form */}
      <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700">
        <h2 className="mb-4 text-lg font-semibold text-slate-900 dark:text-zinc-50"> Añadir lugar</h2>
        <form onSubmit={handleSubmit} className="grid grid-cols-1 gap-3 sm:grid-cols-2">
          <label className="text-sm text-slate-700 dark:text-zinc-200 sm:col-span-2">
            Nombre del lugar
            <input
              type="text"
              name="name"
              value={form.name}
              onChange={handleChange}
              placeholder="Gyeongbokgung Palace, Blue Bottle Coffee…"
                className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-50"
              required
            />
          </label>

          <label className="text-sm text-slate-700 dark:text-zinc-200">
            Barrio / Zona
            <select
              name="district"
              value={form.district}
              onChange={handleChange}
                className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-50"
            >
              <option value="">Selecciona…</option>
              {ZONES.map((z) => (
                <option key={z} value={z}>
                  {z}
                </option>
              ))}
            </select>
          </label>

          <label className="text-sm text-slate-700 dark:text-zinc-200">
            Categoría
            <select
              name="category"
              value={form.category}
              onChange={handleChange}
                className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-50"
            >
              <option value="">Selecciona…</option>
              {PLACE_CATEGORIES.map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </select>
          </label>

          <label className="text-sm text-slate-700 dark:text-zinc-200 sm:col-span-2">
            Nota
            <input
              type="text"
              name="notes"
              value={form.notes}
              onChange={handleChange}
              placeholder="Abrir desde las 9:00, entrada gratuita…"
               className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-50"
            />
          </label>

          <div className="sm:col-span-2">
            <button
              type="submit"
              disabled={saving}
              className="w-full rounded-xl bg-lavender-500 px-5 py-2 text-sm font-medium text-white hover:bg-lavender-600 disabled:cursor-not-allowed disabled:opacity-50 sm:w-auto"
            >
              {saving ? 'Guardando…' : 'Añadir lugar'}
            </button>
          </div>
        </form>
        {error && (
          <p className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700 dark:bg-red-950/40 dark:text-red-300">{error}</p>
        )}
      </div>

      {/* Progress bar */}
      {places.length > 0 && (
          <div className="flex flex-col gap-3 rounded-2xl bg-white px-5 py-3 text-sm shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700 sm:flex-row sm:items-center">
          <span className="text-slate-500">{places.length - visited} por visitar</span>
          <span className="font-medium text-emerald-600">{visited} visitados</span>
          <div className="h-2 flex-1 overflow-hidden rounded-full bg-slate-100">
            <div
              className="h-full rounded-full bg-emerald-500 transition-all duration-500"
              style={{ width: `${places.length ? (visited / places.length) * 100 : 0}%` }}
            />
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="flex flex-col gap-2 sm:flex-row sm:flex-wrap">
        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
          className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm sm:w-auto dark:border-zinc-700 dark:bg-zinc-900/80 dark:text-zinc-50"
        >
          <option value="all">Todos</option>
          <option value="pendiente">Pendientes</option>
          <option value="visitado">Visitados</option>
        </select>

        {availableZones.length > 0 && (
          <select
            value={filterZone}
            onChange={(e) => setFilterZone(e.target.value)}
            className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm sm:w-auto dark:border-zinc-700 dark:bg-zinc-900/80 dark:text-zinc-50"
          >
            <option value="all">Todas las zonas</option>
            {availableZones.map((z) => (
              <option key={z} value={z}>
                {z}
              </option>
            ))}
          </select>
        )}

        {availableCats.length > 0 && (
          <select
            value={filterCat}
            onChange={(e) => setFilterCat(e.target.value)}
            className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm sm:w-auto dark:border-zinc-700 dark:bg-zinc-900/80 dark:text-zinc-50"
          >
            <option value="all">Todas las categorías</option>
            {availableCats.map((c) => (
              <option key={c} value={c}>
                {c}
              </option>
            ))}
          </select>
        )}
      </div>

      {/* Places list */}
      <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700">
        {loading ? (
          <p className="text-sm text-slate-500">Cargando…</p>
        ) : filtered.length === 0 ? (
          <p className="text-sm text-slate-500">
            No hay lugares para los filtros seleccionados.
          </p>
        ) : (
          <ul className="space-y-2">
            {filtered.map((pl) => (
              <li
                key={pl.id}
                className={`flex flex-col gap-3 rounded-xl border p-3 transition-colors sm:flex-row sm:items-start ${
                  pl.status === 'visitado'
                    ? 'border-slate-100 bg-slate-50 opacity-60 dark:border-zinc-800 dark:bg-zinc-900/40'
                    : 'border-slate-200 bg-white dark:border-zinc-700 dark:bg-zinc-900/60'
                }`}
              >
                {/* Checkbox */}
                <button
                  type="button"
                  onClick={() => toggleVisited(pl)}
                  className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-2 transition-colors ${
                    pl.status === 'visitado'
                      ? 'border-emerald-500 bg-emerald-500'
                      : 'border-slate-300 hover:border-lavender-400 dark:border-zinc-600 dark:hover:border-lavender-400'
                  }`}
                >
                  {pl.status === 'visitado' && <span className="text-xs text-white">✓</span>}
                </button>

                <div className="min-w-0 flex-1">
                  <p
                    className={`text-sm font-medium ${
                      pl.status === 'visitado'
                        ? 'text-slate-400 line-through dark:text-zinc-500'
                        : 'text-slate-900 dark:text-zinc-50'
                    }`}
                  >
                    {pl.name}
                  </p>
                  <div className="mt-1 flex flex-wrap gap-1">
                    {pl.district && (
                      <span className="rounded-full bg-blue-100 px-2 py-0.5 text-xs text-blue-700 dark:bg-blue-950/30 dark:text-blue-200">
                        {pl.district}
                      </span>
                    )}
                    {pl.category && (
                      <span
                          className={`rounded-full px-2 py-0.5 text-xs ${CAT_COLORS[pl.category] ?? 'bg-slate-100 text-slate-700 dark:bg-zinc-800/80 dark:text-zinc-200'}`}
                      >
                        {pl.category}
                      </span>
                    )}
                  </div>
                  {pl.notes && (
                    <p className="mt-1 text-xs text-slate-400 dark:text-zinc-400">{pl.notes}</p>
                  )}
                </div>

                <button onClick={() => handleDelete(pl.id)} className="self-end shrink-0 text-lg text-slate-300 hover:text-red-500 dark:hover:text-red-400 sm:self-auto">
                  ×
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { supabase } from '../supabaseClient'
import { toast } from 'sonner'
import { vibrate } from '../utils/haptics'
import CardSkeleton from './Skeletons'

const PLACE_CATEGORIES = ['Cultura', 'Cafés', 'Vistas', 'Compras', 'Restaurantes', 'Ocio', 'Otro']
const ZONES = [
  'Hongdae',
  'Anguk',
  'Insadong',
  'Myeongdong',
  'Gangnam',
  'Itaewon',
  'Dongdaemun',
  'Busan',
  'Gyeongju',
  'Otro',
]

const CAT_COLORS = {
  Cultura: 'bg-amber-100 text-amber-700',
  Cafés: 'bg-brown-100 text-yellow-800',
  Vistas: 'bg-sky-100 text-sky-700',
  Compras: 'bg-pink-100 text-pink-700',
  Restaurantes: 'bg-orange-100 text-orange-700',
  Ocio: 'bg-purple-100 text-purple-700',
  Otro: 'bg-slate-100 text-slate-700',
}

export default function PlacesToVisit() {
  const [places, setPlaces] = useState([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')

  const [filterStatus, setFilterStatus] = useState('all')
  const [filterZone, setFilterZone] = useState('all')
  const [filterCat, setFilterCat] = useState('all')

  const [form, setForm] = useState({ name: '', district: '', category: '', notes: '' })

  useEffect(() => {
    void fetchPlaces()
  }, [])

  async function fetchPlaces() {
    setLoading(true)
    const { data, error: e } = await supabase
      .from('places')
      .select('id, name, district, category, status, notes, created_at')
      .order('status', { ascending: true })
      .order('created_at', { ascending: false })
    if (e) {
      setError(e.message)
      setLoading(false)
      return
    }
    setPlaces(data ?? [])
    setLoading(false)
  }

  function handleChange(ev) {
    const { name, value } = ev.target
    setForm((p) => ({ ...p, [name]: value }))
  }

  async function handleSubmit(ev) {
    ev.preventDefault()
    if (!form.name.trim()) {
      setError('El nombre del lugar es obligatorio.')
      return
    }
    setSaving(true)
    setError('')
    const { data, error: e } = await supabase
      .from('places')
      .insert({
        name: form.name.trim(),
        city: 'Korea',
        district: form.district || null,
        category: form.category || null,
        notes: form.notes.trim() || null,
        status: 'pendiente',
      })
      .select('id, name, district, category, status, notes, created_at')
      .single()
    if (e) {
      setError(e.message)
      setSaving(false)
      return
    }
    setPlaces((p) => [data, ...p])
    setForm({ name: '', district: '', category: '', notes: '' })
    setSaving(false)
    toast.success('Lugar añadido')
    vibrate(15)
  }

  async function toggleVisited(place) {
    const newStatus = place.status === 'visitado' ? 'pendiente' : 'visitado'
    const { error: e } = await supabase
      .from('places')
      .update({ status: newStatus })
      .eq('id', place.id)
    if (e) {
      setError(e.message)
      return
    }
    setPlaces((p) => p.map((pl) => (pl.id === place.id ? { ...pl, status: newStatus } : pl)))
    toast.success(newStatus === 'visitado' ? 'Marcado como visitado' : 'Marcado como pendiente')
    vibrate(10)
  }

  async function handleDelete(id) {
    const { error: e } = await supabase.from('places').delete().eq('id', id)
    if (e) {
      setError(e.message)
      return
    }
    setPlaces((p) => p.filter((pl) => pl.id !== id))
    toast.success('Lugar eliminado')
    vibrate(15)
  }

  const visited = places.filter((p) => p.status === 'visitado').length

  // Dynamic filter options from actual data
  const availableZones = useMemo(
    () => [...new Set(places.map((p) => p.district).filter(Boolean))],
    [places],
  )
  const availableCats = useMemo(
    () => [...new Set(places.map((p) => p.category).filter(Boolean))],
    [places],
  )

  const filtered = places.filter((pl) => {
    const statusMatch = filterStatus === 'all' || pl.status === filterStatus
    const zoneMatch = filterZone === 'all' || pl.district === filterZone
    const catMatch = filterCat === 'all' || pl.category === filterCat
    return statusMatch && zoneMatch && catMatch
  })

  return (
    <div className="space-y-4">
      {/* Form */}
      <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700">
        <h2 className="mb-4 text-lg font-semibold text-slate-900 dark:text-zinc-50"> Añadir lugar</h2>
        <form onSubmit={handleSubmit} className="grid grid-cols-1 gap-3 sm:grid-cols-2">
          <label className="text-sm text-slate-700 dark:text-zinc-200 sm:col-span-2">
            Nombre del lugar
            <input
              type="text"
              name="name"
              value={form.name}
              onChange={handleChange}
              placeholder="Gyeongbokgung Palace, Blue Bottle Coffee…"
                className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-50"
              required
            />
          </label>

          <label className="text-sm text-slate-700 dark:text-zinc-200">
            Barrio / Zona
            <select
              name="district"
              value={form.district}
              onChange={handleChange}
                className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-50"
            >
              <option value="">Selecciona…</option>
              {ZONES.map((z) => (
                <option key={z} value={z}>
                  {z}
                </option>
              ))}
            </select>
          </label>

          <label className="text-sm text-slate-700 dark:text-zinc-200">
            Categoría
            <select
              name="category"
              value={form.category}
              onChange={handleChange}
                className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-50"
            >
              <option value="">Selecciona…</option>
              {PLACE_CATEGORIES.map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </select>
          </label>

          <label className="text-sm text-slate-700 dark:text-zinc-200 sm:col-span-2">
            Nota
            <input
              type="text"
              name="notes"
              value={form.notes}
              onChange={handleChange}
              placeholder="Abrir desde las 9:00, entrada gratuita…"
               className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-50"
            />
          </label>

          <div className="sm:col-span-2">
            <button
              type="submit"
              disabled={saving}
              className="w-full rounded-xl bg-lavender-500 px-5 py-2 text-sm font-medium text-white hover:bg-lavender-600 disabled:cursor-not-allowed disabled:opacity-50 sm:w-auto"
            >
              {saving ? 'Guardando…' : 'Añadir lugar'}
            </button>
          </div>
        </form>
        {error && (
          <p className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700 dark:bg-red-950/40 dark:text-red-300">{error}</p>
        )}
      </div>

      {/* Progress bar */}
      {places.length > 0 && (
          <div className="flex flex-col gap-3 rounded-2xl bg-white px-5 py-3 text-sm shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700 sm:flex-row sm:items-center">
          <span className="text-slate-500">{places.length - visited} por visitar</span>
          <span className="font-medium text-emerald-600">{visited} visitados</span>
          <div className="h-2 flex-1 overflow-hidden rounded-full bg-slate-100">
            <div
              className="h-full rounded-full bg-emerald-500 transition-all duration-500"
              style={{ width: `${places.length ? (visited / places.length) * 100 : 0}%` }}
            />
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="flex flex-col gap-2 sm:flex-row sm:flex-wrap">
        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
          className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm sm:w-auto dark:border-zinc-700 dark:bg-zinc-900/80 dark:text-zinc-50"
        >
          <option value="all">Todos</option>
          <option value="pendiente">Pendientes</option>
          <option value="visitado">Visitados</option>
        </select>

        {availableZones.length > 0 && (
          <select
            value={filterZone}
            onChange={(e) => setFilterZone(e.target.value)}
            className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm sm:w-auto dark:border-zinc-700 dark:bg-zinc-900/80 dark:text-zinc-50"
          >
            <option value="all">Todas las zonas</option>
            {availableZones.map((z) => (
              <option key={z} value={z}>
                {z}
              </option>
            ))}
          </select>
        )}

        {availableCats.length > 0 && (
          <select
            value={filterCat}
            onChange={(e) => setFilterCat(e.target.value)}
            className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm sm:w-auto dark:border-zinc-700 dark:bg-zinc-900/80 dark:text-zinc-50"
          >
            <option value="all">Todas las categorías</option>
            {availableCats.map((c) => (
              <option key={c} value={c}>
                {c}
              </option>
            ))}
          </select>
        )}
      </div>

      {/* Places list */}
      <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700">
        {loading ? (
          <div className="space-y-3">
            <CardSkeleton />
            <CardSkeleton />
            <CardSkeleton />
          </div>
        ) : filtered.length === 0 ? (
          <p className="text-sm text-slate-500">
            No hay lugares para los filtros seleccionados.
          </p>
        ) : (
          <ul className="space-y-2">
            {filtered.map((pl) => (
              <li
                key={pl.id}
                className={`flex flex-col gap-3 rounded-xl border p-3 transition-colors sm:flex-row sm:items-start ${
                  pl.status === 'visitado'
                    ? 'border-slate-100 bg-slate-50 opacity-60 dark:border-zinc-800 dark:bg-zinc-900/40'
                    : 'border-slate-200 bg-white dark:border-zinc-700 dark:bg-zinc-900/60'
                }`}
              >
                {/* Checkbox */}
                <button
                  type="button"
                  onClick={() => toggleVisited(pl)}
                  className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-2 transition-colors ${
                    pl.status === 'visitado'
                      ? 'border-emerald-500 bg-emerald-500'
                      : 'border-slate-300 hover:border-lavender-400 dark:border-zinc-600 dark:hover:border-lavender-400'
                  }`}
                >
                  {pl.status === 'visitado' && <span className="text-xs text-white">✓</span>}
                </button>

                <div className="min-w-0 flex-1">
                  <p
                    className={`text-sm font-medium ${
                      pl.status === 'visitado'
                        ? 'text-slate-400 line-through dark:text-zinc-500'
                        : 'text-slate-900 dark:text-zinc-50'
                    }`}
                  >
                    {pl.name}
                  </p>
                  <div className="mt-1 flex flex-wrap gap-1">
                    {pl.district && (
                      <span className="rounded-full bg-blue-100 px-2 py-0.5 text-xs text-blue-700 dark:bg-blue-950/30 dark:text-blue-200">
                        {pl.district}
                      </span>
                    )}
                    {pl.category && (
                      <span
                          className={`rounded-full px-2 py-0.5 text-xs ${CAT_COLORS[pl.category] ?? 'bg-slate-100 text-slate-700 dark:bg-zinc-800/80 dark:text-zinc-200'}`}
                      >
                        {pl.category}
                      </span>
                    )}
                  </div>
                  {pl.notes && (
                    <p className="mt-1 text-xs text-slate-400 dark:text-zinc-400">{pl.notes}</p>
                  )}
                </div>

                <button onClick={() => handleDelete(pl.id)} className="self-end shrink-0 text-lg text-slate-300 hover:text-red-500 dark:hover:text-red-400 sm:self-auto">
                  ×
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  )
}

import { useRef, useState } from 'react'
import { jsPDF } from 'jspdf'
import { createWorker } from 'tesseract.js'
import { supabase } from '../supabaseClient'

/**
 * Extrae cantidad en KRW y fecha del texto OCR
 */
function extractDataFromOCR(text) {
  const normalized = text.replace(/[\r\t]+/g, ' ').replace(/\s{2,}/g, ' ')
  const lines = normalized.split('\n').map((line) => line.trim()).filter(Boolean)

  // 1) Buscar líneas que suelen contener totales
  const preferredLines = lines.filter((line) =>
    /(total|합계|총액|결제금액|금액|amount|grand total|subtotal)/i.test(line)
  )

  const candidateLines = preferredLines.length > 0 ? preferredLines : lines
  const amounts = []

  for (const line of candidateLines) {
    const hasCurrency = /(₩|krw|won|원)/i.test(line)
    const matches = line.match(/\d{1,3}(?:[,.]\d{3})+|\d{4,}/g) || []
    for (const raw of matches) {
      const parsed = Number(raw.replace(/[,.]/g, ''))
      if (!Number.isNaN(parsed) && parsed > 0 && (hasCurrency || parsed >= 1000)) {
        amounts.push(parsed)
      }
    }
  }

  const amount = amounts.length ? Math.max(...amounts) : null

  // 2) Soportar fechas 2026-07-22 / 2026.07.22 / 2026년 07월 22일
  const datePatterns = [
    /(\d{4})[./-](\d{1,2})[./-](\d{1,2})/i,
    /(\d{4})\s*년\s*(\d{1,2})\s*월\s*(\d{1,2})\s*일/i,
  ]

  let date = null
  for (const re of datePatterns) {
    const match = normalized.match(re)
    if (match) {
      const [, year, month, day] = match
      date = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
      break
    }
  }

  return { amount, date, lines }
}

function translateLineToSpanish(line) {
  return line
    .replace(/\bTOTAL\b/gi, 'TOTAL')
    .replace(/\bSUBTOTAL\b/gi, 'SUBTOTAL')
    .replace(/\bVAT\b/gi, 'IVA')
    .replace(/\bTAX\b/gi, 'IMPUESTO')
    .replace(/\bCASH\b/gi, 'EFECTIVO')
    .replace(/\bCARD\b/gi, 'TARJETA')
    .replace(/\bRECEIPT\b/gi, 'TICKET')
    .replace(/합계/g, 'TOTAL')
    .replace(/총액/g, 'TOTAL')
    .replace(/부가세/g, 'IVA')
    .replace(/현금/g, 'EFECTIVO')
    .replace(/카드/g, 'TARJETA')
}

function buildReceiptSummaryEs(text, extracted) {
  const lines = extracted.lines || []

  const merchant = lines.find((line) => {
    if (line.length < 3 || line.length > 45) return false
    if (/\d{3,}/.test(line)) return false
    return /[A-Za-z가-힣]/.test(line)
  })

  const detailLines = lines
    .filter((line) => /(total|합계|총액|vat|tax|card|cash|현금|카드|부가세|menu|item)/i.test(line))
    .slice(0, 4)
    .map((line) => `- ${translateLineToSpanish(line)}`)

  const parts = []
  if (merchant) parts.push(`Comercio: ${translateLineToSpanish(merchant)}`)
  if (extracted.date) parts.push(`Fecha: ${extracted.date}`)
  if (extracted.amount) parts.push(`Total estimado: ${extracted.amount.toLocaleString('es-ES')} KRW`)

  const header = parts.length ? parts.join(' | ') : 'No se detectaron datos estructurados del ticket.'
  if (!detailLines.length) return header

  return `${header}\n${detailLines.join('\n')}`
}

/**
 * Genera archivo PDF a partir de una imagen
 */
function generatePDFFromImage(imageDataUrl, filename) {
  try {
    const img = new Image()
    img.onload = () => {
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4',
      })
      const pdfWidth = pdf.internal.pageSize.getWidth()
      const pdfHeight = (img.height / img.width) * pdfWidth
      pdf.addImage(imageDataUrl, 'JPEG', 0, 0, pdfWidth, Math.min(pdfHeight, pdf.internal.pageSize.getHeight()))
      pdf.save(filename || 'receipt.pdf')
    }
    img.src = imageDataUrl
  } catch (err) {
    throw new Error(`Error al generar PDF: ${err.message}`)
  }
}

export default function ReceiptUploader({ onExtractData, onUploadSuccess, onSummaryGenerated }) {
  const [mode, setMode] = useState(null) // 'upload' | 'pdf' | 'ocr'
  const [uploading, setUploading] = useState(false)
  const [ocrProcessing, setOcrProcessing] = useState(false)
  const [error, setError] = useState('')
  const [info, setInfo] = useState('')
  const [ocrSummary, setOcrSummary] = useState('')
  const fileInputRef = useRef(null)
  const [capturedImage, setCapturedImage] = useState(null)

  async function uploadFileToSupabase(file, fileType) {
    setError('')
    setInfo('')
    setUploading(true)

    try {
      const timestamp = Date.now()
      const filename = `${timestamp}_${file.name}`
      const path = `${filename}`

      const { error: uploadError } = await supabase.storage
        .from('receipts')
        .upload(path, file, { cacheControl: '3600', upsert: false })

      if (uploadError) return setError(`Error al subir: ${uploadError.message}`)

      const { data } = supabase.storage.from('receipts').getPublicUrl(path)
      const publicUrl = data.publicUrl

      setInfo(`${fileType} subido correctamente.`)
      onUploadSuccess?.({ url: publicUrl, path, filename })

      return publicUrl
    } catch (err) {
      setError(`Error al subir: ${err.message}`)
      return null
    } finally {
      setUploading(false)
    }
  }

  async function handleImageSelect(e) {
    const file = e.target.files?.[0]
    if (!file) return

    const reader = new FileReader()
    reader.onload = (event) => {
      setCapturedImage(event.target.result)
      setInfo('Imagen cargada. Elige una acción:')
    }
    reader.readAsDataURL(file)
  }

  async function handleUploadImage() {
    if (!capturedImage) return

    setUploading(true)
    setError('')
    setInfo('')

    try {
      const response = await fetch(capturedImage)
      const blob = await response.blob()
      const file = new File([blob], `receipt_${Date.now()}.jpg`, { type: 'image/jpeg' })

      const publicUrl = await uploadFileToSupabase(file, 'Imagen')
      if (publicUrl) {
        setCapturedImage(null)
        setMode(null)
      }
    } catch (err) {
      setError(`Error: ${err.message}`)
    } finally {
      setUploading(false)
    }
  }

  async function handleConvertToPDF() {
    if (!capturedImage) return

    setError('')
    setInfo('')

    try {
      generatePDFFromImage(capturedImage, 'receipt.pdf')

      // Convertir canvas a blob y subir
      const canvas = document.createElement('canvas')
      const ctx = canvas.getContext('2d')
      const img = new Image()

      img.onload = async () => {
        canvas.width = img.width
        canvas.height = img.height
        ctx.drawImage(img, 0, 0)

        canvas.toBlob(async () => {
          const pdf = new jsPDF({
            orientation: 'portrait',
            unit: 'mm',
            format: 'a4',
          })
          const pdfWidth = pdf.internal.pageSize.getWidth()
          const pdfHeight = (img.height / img.width) * pdfWidth
          const imgData = canvas.toDataURL('image/jpeg')
          pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, Math.min(pdfHeight, pdf.internal.pageSize.getHeight()))

          const pdfBlob = pdf.output('blob')
          const file = new File([pdfBlob], `receipt_${Date.now()}.pdf`, { type: 'application/pdf' })

          await uploadFileToSupabase(file, 'PDF')
          setCapturedImage(null)
          setMode(null)
        }, 'image/jpeg')
      }

      img.src = capturedImage
    } catch (err) {
      setError(`Error al convertir PDF: ${err.message}`)
    }
  }

  async function handleOCRExtraction() {
    if (!capturedImage) return

    setOcrProcessing(true)
    setError('')
    setInfo('')

    try {
      const worker = await createWorker('kor+eng+spa')

      const { data } = await worker.recognize(capturedImage)
      const extractedText = data.text || ''

      const extracted = extractDataFromOCR(extractedText)
      const summary = buildReceiptSummaryEs(extractedText, extracted)
      setOcrSummary(summary)
      onSummaryGenerated?.(summary)

      await worker.terminate()

      if (!extracted.amount && !extracted.date) {
        setInfo('No se pudo detectar cantidad/fecha con precisión, pero se generó un resumen OCR.')
      } else {
        const extractedData = {}
        if (extracted.amount) {
          extractedData.amount_krw = extracted.amount
        }
        if (extracted.date) {
          extractedData.expense_date = extracted.date
        }
        onExtractData?.(extractedData)
        setInfo(
          `Detectado: ${extracted.amount ? `${extracted.amount.toLocaleString('es-ES')} KRW` : ''} ${extracted.date ? `- Fecha: ${extracted.date}` : ''}`
        )
      }

      // Subir la imagen también
      const response = await fetch(capturedImage)
      const blob = await response.blob()
      const file = new File([blob], `receipt_ocr_${Date.now()}.jpg`, { type: 'image/jpeg' })
      await uploadFileToSupabase(file, 'Imagen (OCR)')

      setCapturedImage(null)
      setMode(null)
    } catch (err) {
      setError(`Error en OCR: ${err.message}`)
    } finally {
      setOcrProcessing(false)
    }
  }

  if (!capturedImage) {
    return (
      <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700">
        <h3 className="mb-3 font-semibold text-slate-900 dark:text-zinc-50"> Ticket / Recibo</h3>
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          onChange={handleImageSelect}
          className="hidden"
        />
        <button
          type="button"
          onClick={() => fileInputRef.current?.click()}
          className="w-full rounded-xl border-2 border-dashed border-slate-300 px-4 py-6
                     text-center transition-colors hover:border-lavender-400 dark:border-zinc-700 dark:bg-zinc-900/50 dark:hover:border-lavender-500"
        >
          <p className="text-sm font-medium text-slate-700 dark:text-zinc-200">Selecciona una foto de recibo</p>
          <p className="mt-1 text-xs text-slate-400 dark:text-zinc-500">JPG o PNG</p>
        </button>
      </div>
    )
  }

  return (
    <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700">
      <h3 className="mb-3 font-semibold text-slate-900 dark:text-zinc-50"> Ticket / Recibo</h3>

      {/* Preview */}
      <div className="mb-4 overflow-hidden rounded-xl bg-slate-50 dark:bg-zinc-800/60">
        <img src={capturedImage} alt="Recibo" className="aspect-[4/3] h-auto w-full max-h-64 object-contain" />
      </div>

      {/* Mode selector */}
      <div className="mb-4 space-y-2">
        <button
          type="button"
          onClick={() => setMode('upload')}
          disabled={uploading}
          className={`w-full rounded-lg px-3 py-2 text-sm font-medium transition-colors
                      ${mode === 'upload'
                        ? 'bg-lavender-500 text-white'
                          : 'bg-slate-100 text-slate-700 hover:bg-slate-200 dark:bg-zinc-800/70 dark:text-zinc-200 dark:hover:bg-zinc-700/80'}`}
        >
          {uploading ? '⏳ Subiendo…' : '☁️ Subir imagen'}
        </button>

        <button
          type="button"
          onClick={() => setMode('pdf')}
          disabled={uploading}
          className={`w-full rounded-lg px-3 py-2 text-sm font-medium transition-colors
                      ${mode === 'pdf'
                        ? 'bg-lavender-500 text-white'
                          : 'bg-slate-100 text-slate-700 hover:bg-slate-200 dark:bg-zinc-800/70 dark:text-zinc-200 dark:hover:bg-zinc-700/80'}`}
        >
          {uploading ? '⏳ Subiendo…' : ' Convertir a PDF'}
        </button>

        <button
          type="button"
          onClick={() => setMode('ocr')}
          disabled={ocrProcessing}
          className={`w-full rounded-lg px-3 py-2 text-sm font-medium transition-colors
                      ${mode === 'ocr'
                        ? 'bg-lavender-500 text-white'
                          : 'bg-slate-100 text-slate-700 hover:bg-slate-200 dark:bg-zinc-800/70 dark:text-zinc-200 dark:hover:bg-zinc-700/80'}`}
        >
          {ocrProcessing ? '⏳ Escaneando…' : ' Escanear (OCR)'}
        </button>
      </div>

      {/* Action buttons */}
      {mode === 'upload' && (
        <button
          type="button"
          onClick={handleUploadImage}
          disabled={uploading}
          className="w-full rounded-xl bg-lavender-500 px-4 py-2 text-sm font-medium text-white
                     hover:bg-lavender-600 disabled:opacity-50"
        >
          {uploading ? 'Subiendo…' : 'Confirmar subida'}
        </button>
      )}

      {mode === 'pdf' && (
        <button
          type="button"
          onClick={handleConvertToPDF}
          disabled={uploading}
          className="w-full rounded-xl bg-lavender-500 px-4 py-2 text-sm font-medium text-white
                     hover:bg-lavender-600 disabled:opacity-50"
        >
          {uploading ? 'Convirtiendo…' : 'Convertir y subir PDF'}
        </button>
      )}

      {mode === 'ocr' && (
        <button
          type="button"
          onClick={handleOCRExtraction}
          disabled={ocrProcessing}
          className="w-full rounded-xl bg-lavender-500 px-4 py-2 text-sm font-medium text-white
                     hover:bg-lavender-600 disabled:opacity-50"
        >
          {ocrProcessing ? 'Escaneando…' : 'Escanear e identificar datos'}
        </button>
      )}

      {/* Messages */}
      {error && (
        <p className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-xs text-red-700 dark:bg-red-950/30 dark:text-red-200">{error}</p>
      )}
      {info && (
        <p className="mt-3 rounded-lg bg-blue-50 px-3 py-2 text-xs text-blue-700 dark:bg-blue-950/30 dark:text-blue-200">{info}</p>
      )}

      {ocrSummary && (
        <div className="mt-3 rounded-lg bg-zinc-50 px-3 py-2 text-xs text-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-200">
          <p className="mb-1 font-semibold">Resumen OCR (español):</p>
          <pre className="whitespace-pre-wrap font-sans">{ocrSummary}</pre>
        </div>
      )}

      {/* Cancel */}
      <button
        type="button"
        onClick={() => {
          setCapturedImage(null)
          setMode(null)
          setError('')
          setInfo('')
          setOcrSummary('')
        }}
        className="mt-3 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm
                   text-slate-700 hover:bg-slate-50 dark:border-zinc-700 dark:bg-zinc-900/80 dark:text-zinc-200 dark:hover:bg-zinc-800"
      >
        Cancelar
      </button>
    </div>
  )
}

import { useRef, useState } from 'react'
import { jsPDF } from 'jspdf'
import { createWorker } from 'tesseract.js'
import { supabase } from '../supabaseClient'
import { toast } from 'sonner'
import { vibrate } from '../utils/haptics'

/**
 * Extrae cantidad en KRW y fecha del texto OCR
 */
function extractDataFromOCR(text) {
  const normalized = text.replace(/[\r\t]+/g, ' ').replace(/\s{2,}/g, ' ')
  const lines = normalized.split('\n').map((line) => line.trim()).filter(Boolean)

  // 1) Buscar líneas que suelen contener totales
  const preferredLines = lines.filter((line) =>
    /(total|합계|총액|결제금액|금액|amount|grand total|subtotal)/i.test(line)
  )

  const candidateLines = preferredLines.length > 0 ? preferredLines : lines
  const amounts = []

  for (const line of candidateLines) {
    const hasCurrency = /(₩|krw|won|원)/i.test(line)
    const matches = line.match(/\d{1,3}(?:[,.]\d{3})+|\d{4,}/g) || []
    for (const raw of matches) {
      const parsed = Number(raw.replace(/[,.]/g, ''))
      if (!Number.isNaN(parsed) && parsed > 0 && (hasCurrency || parsed >= 1000)) {
        amounts.push(parsed)
      }
    }
  }

  const amount = amounts.length ? Math.max(...amounts) : null

  // 2) Soportar fechas 2026-07-22 / 2026.07.22 / 2026년 07월 22일
  const datePatterns = [
    /(\d{4})[./-](\d{1,2})[./-](\d{1,2})/i,
    /(\d{4})\s*년\s*(\d{1,2})\s*월\s*(\d{1,2})\s*일/i,
  ]

  let date = null
  for (const re of datePatterns) {
    const match = normalized.match(re)
    if (match) {
      const [, year, month, day] = match
      date = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
      break
    }
  }

  return { amount, date, lines }
}

function translateLineToSpanish(line) {
  return line
    .replace(/\bTOTAL\b/gi, 'TOTAL')
    .replace(/\bSUBTOTAL\b/gi, 'SUBTOTAL')
    .replace(/\bVAT\b/gi, 'IVA')
    .replace(/\bTAX\b/gi, 'IMPUESTO')
    .replace(/\bCASH\b/gi, 'EFECTIVO')
    .replace(/\bCARD\b/gi, 'TARJETA')
    .replace(/\bRECEIPT\b/gi, 'TICKET')
    .replace(/합계/g, 'TOTAL')
    .replace(/총액/g, 'TOTAL')
    .replace(/부가세/g, 'IVA')
    .replace(/현금/g, 'EFECTIVO')
    .replace(/카드/g, 'TARJETA')
}

function buildReceiptSummaryEs(text, extracted) {
  const lines = extracted.lines || []

  const merchant = lines.find((line) => {
    if (line.length < 3 || line.length > 45) return false
    if (/\d{3,}/.test(line)) return false
    return /[A-Za-z가-힣]/.test(line)
  })

  const detailLines = lines
    .filter((line) => /(total|합계|총액|vat|tax|card|cash|현금|카드|부가세|menu|item)/i.test(line))
    .slice(0, 4)
    .map((line) => `- ${translateLineToSpanish(line)}`)

  const parts = []
  if (merchant) parts.push(`Comercio: ${translateLineToSpanish(merchant)}`)
  if (extracted.date) parts.push(`Fecha: ${extracted.date}`)
  if (extracted.amount) parts.push(`Total estimado: ${extracted.amount.toLocaleString('es-ES')} KRW`)

  const header = parts.length ? parts.join(' | ') : 'No se detectaron datos estructurados del ticket.'
  if (!detailLines.length) return header

  return `${header}\n${detailLines.join('\n')}`
}

/**
 * Genera archivo PDF a partir de una imagen
 */
function generatePDFFromImage(imageDataUrl, filename) {
  try {
    const img = new Image()
    img.onload = () => {
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4',
      })
      const pdfWidth = pdf.internal.pageSize.getWidth()
      const pdfHeight = (img.height / img.width) * pdfWidth
      pdf.addImage(imageDataUrl, 'JPEG', 0, 0, pdfWidth, Math.min(pdfHeight, pdf.internal.pageSize.getHeight()))
      pdf.save(filename || 'receipt.pdf')
    }
    img.src = imageDataUrl
  } catch (err) {
    throw new Error(`Error al generar PDF: ${err.message}`)
  }
}

export default function ReceiptUploader({ onExtractData, onUploadSuccess, onSummaryGenerated }) {
  const [mode, setMode] = useState(null) // 'upload' | 'pdf' | 'ocr'
  const [uploading, setUploading] = useState(false)
  const [ocrProcessing, setOcrProcessing] = useState(false)
  const [error, setError] = useState('')
  const [info, setInfo] = useState('')
  const [ocrSummary, setOcrSummary] = useState('')
  const fileInputRef = useRef(null)
  const [capturedImage, setCapturedImage] = useState(null)

  async function uploadFileToSupabase(file, fileType) {
    setError('')
    setInfo('')
    setUploading(true)

    try {
      const timestamp = Date.now()
      const filename = `${timestamp}_${file.name}`
      const path = `${filename}`

      const { error: uploadError } = await supabase.storage
        .from('receipts')
        .upload(path, file, { cacheControl: '3600', upsert: false })

      if (uploadError) return setError(`Error al subir: ${uploadError.message}`)

      const { data } = supabase.storage.from('receipts').getPublicUrl(path)
      const publicUrl = data.publicUrl

      setInfo(`${fileType} subido correctamente.`)
      onUploadSuccess?.({ url: publicUrl, path, filename })
      // Notificar al usuario
      try {
        toast.success(`${fileType} subido correctamente`)
        vibrate(12)
      } catch (err) {
        // no-op
      }

      return publicUrl
    } catch (err) {
      setError(`Error al subir: ${err.message}`)
      return null
    } finally {
      setUploading(false)
    }
  }

  async function handleImageSelect(e) {
    const file = e.target.files?.[0]
    if (!file) return

    const reader = new FileReader()
    reader.onload = (event) => {
      setCapturedImage(event.target.result)
      setInfo('Imagen cargada. Elige una acción:')
    }
    reader.readAsDataURL(file)
  }

  async function handleUploadImage() {
    if (!capturedImage) return

    setUploading(true)
    setError('')
    setInfo('')

    try {
      const response = await fetch(capturedImage)
      const blob = await response.blob()
      const file = new File([blob], `receipt_${Date.now()}.jpg`, { type: 'image/jpeg' })

      const publicUrl = await uploadFileToSupabase(file, 'Imagen')
      if (publicUrl) {
        setCapturedImage(null)
        setMode(null)
      }
    } catch (err) {
      setError(`Error: ${err.message}`)
    } finally {
      setUploading(false)
    }
  }

  async function handleConvertToPDF() {
    if (!capturedImage) return

    setError('')
    setInfo('')

    try {
      generatePDFFromImage(capturedImage, 'receipt.pdf')

      // Convertir canvas a blob y subir
      const canvas = document.createElement('canvas')
      const ctx = canvas.getContext('2d')
      const img = new Image()

      img.onload = async () => {
        canvas.width = img.width
        canvas.height = img.height
        ctx.drawImage(img, 0, 0)

        canvas.toBlob(async () => {
          const pdf = new jsPDF({
            orientation: 'portrait',
            unit: 'mm',
            format: 'a4',
          })
          const pdfWidth = pdf.internal.pageSize.getWidth()
          const pdfHeight = (img.height / img.width) * pdfWidth
          const imgData = canvas.toDataURL('image/jpeg')
          pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, Math.min(pdfHeight, pdf.internal.pageSize.getHeight()))

          const pdfBlob = pdf.output('blob')
          const file = new File([pdfBlob], `receipt_${Date.now()}.pdf`, { type: 'application/pdf' })

          await uploadFileToSupabase(file, 'PDF')
          setCapturedImage(null)
          setMode(null)
        }, 'image/jpeg')
      }

      img.src = capturedImage
    } catch (err) {
      setError(`Error al convertir PDF: ${err.message}`)
    }
  }

  async function handleOCRExtraction() {
    if (!capturedImage) return

    setOcrProcessing(true)
    setError('')
    setInfo('')

    try {
      const worker = await createWorker('kor+eng+spa')

      const { data } = await worker.recognize(capturedImage)
      const extractedText = data.text || ''

      const extracted = extractDataFromOCR(extractedText)
      const summary = buildReceiptSummaryEs(extractedText, extracted)
      setOcrSummary(summary)
      onSummaryGenerated?.(summary)

      await worker.terminate()

      if (!extracted.amount && !extracted.date) {
        setInfo('No se pudo detectar cantidad/fecha con precisión, pero se generó un resumen OCR.')
        try { toast('Resumen OCR generado'); vibrate(10) } catch (err) { }
      } else {
        const extractedData = {}
        if (extracted.amount) {
          extractedData.amount_krw = extracted.amount
        }
        if (extracted.date) {
          extractedData.expense_date = extracted.date
        }
        onExtractData?.(extractedData)
        setInfo(
          `Detectado: ${extracted.amount ? `${extracted.amount.toLocaleString('es-ES')} KRW` : ''} ${extracted.date ? `- Fecha: ${extracted.date}` : ''}`
        )
        try { toast.success('Datos detectados desde OCR'); vibrate(12) } catch (err) { }
      }

      // Subir la imagen también
      const response = await fetch(capturedImage)
      const blob = await response.blob()
      const file = new File([blob], `receipt_ocr_${Date.now()}.jpg`, { type: 'image/jpeg' })
      await uploadFileToSupabase(file, 'Imagen (OCR)')

      setCapturedImage(null)
      setMode(null)
    } catch (err) {
      setError(`Error en OCR: ${err.message}`)
    } finally {
      setOcrProcessing(false)
    }
  }

  if (!capturedImage) {
    return (
      <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700">
        <h3 className="mb-3 font-semibold text-slate-900 dark:text-zinc-50"> Ticket / Recibo</h3>
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          onChange={handleImageSelect}
          className="hidden"
        />
        <button
          type="button"
          onClick={() => fileInputRef.current?.click()}
          className="w-full rounded-xl border-2 border-dashed border-slate-300 px-4 py-6
                     text-center transition-colors hover:border-lavender-400 dark:border-zinc-700 dark:bg-zinc-900/50 dark:hover:border-lavender-500"
        >
          <p className="text-sm font-medium text-slate-700 dark:text-zinc-200">Selecciona una foto de recibo</p>
          <p className="mt-1 text-xs text-slate-400 dark:text-zinc-500">JPG o PNG</p>
        </button>
      </div>
    )
  }

  return (
    <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700">
      <h3 className="mb-3 font-semibold text-slate-900 dark:text-zinc-50"> Ticket / Recibo</h3>

      {/* Preview */}
      <div className="mb-4 overflow-hidden rounded-xl bg-slate-50 dark:bg-zinc-800/60">
        <img src={capturedImage} alt="Recibo" className="aspect-[4/3] h-auto w-full max-h-64 object-contain" />
      </div>

      {/* Mode selector */}
      <div className="mb-4 space-y-2">
        <button
          type="button"
          onClick={() => setMode('upload')}
          disabled={uploading}
          className={`w-full rounded-lg px-3 py-2 text-sm font-medium transition-colors
                      ${mode === 'upload'
                        ? 'bg-lavender-500 text-white'
                          : 'bg-slate-100 text-slate-700 hover:bg-slate-200 dark:bg-zinc-800/70 dark:text-zinc-200 dark:hover:bg-zinc-700/80'}`}
        >
          {uploading ? '⏳ Subiendo…' : '☁️ Subir imagen'}
        </button>

        <button
          type="button"
          onClick={() => setMode('pdf')}
          disabled={uploading}
          className={`w-full rounded-lg px-3 py-2 text-sm font-medium transition-colors
                      ${mode === 'pdf'
                        ? 'bg-lavender-500 text-white'
                          : 'bg-slate-100 text-slate-700 hover:bg-slate-200 dark:bg-zinc-800/70 dark:text-zinc-200 dark:hover:bg-zinc-700/80'}`}
        >
          {uploading ? '⏳ Subiendo…' : ' Convertir a PDF'}
        </button>

        <button
          type="button"
          onClick={() => setMode('ocr')}
          disabled={ocrProcessing}
          className={`w-full rounded-lg px-3 py-2 text-sm font-medium transition-colors
                      ${mode === 'ocr'
                        ? 'bg-lavender-500 text-white'
                          : 'bg-slate-100 text-slate-700 hover:bg-slate-200 dark:bg-zinc-800/70 dark:text-zinc-200 dark:hover:bg-zinc-700/80'}`}
        >
          {ocrProcessing ? '⏳ Escaneando…' : ' Escanear (OCR)'}
        </button>
      </div>

      {/* Action buttons */}
      {mode === 'upload' && (
        <button
          type="button"
          onClick={handleUploadImage}
          disabled={uploading}
          className="w-full rounded-xl bg-lavender-500 px-4 py-2 text-sm font-medium text-white
                     hover:bg-lavender-600 disabled:opacity-50"
        >
          {uploading ? 'Subiendo…' : 'Confirmar subida'}
        </button>
      )}

      {mode === 'pdf' && (
        <button
          type="button"
          onClick={handleConvertToPDF}
          disabled={uploading}
          className="w-full rounded-xl bg-lavender-500 px-4 py-2 text-sm font-medium text-white
                     hover:bg-lavender-600 disabled:opacity-50"
        >
          {uploading ? 'Convirtiendo…' : 'Convertir y subir PDF'}
        </button>
      )}

      {mode === 'ocr' && (
        <button
          type="button"
          onClick={handleOCRExtraction}
          disabled={ocrProcessing}
          className="w-full rounded-xl bg-lavender-500 px-4 py-2 text-sm font-medium text-white
                     hover:bg-lavender-600 disabled:opacity-50"
        >
          {ocrProcessing ? 'Escaneando…' : 'Escanear e identificar datos'}
        </button>
      )}

      {/* Messages */}
      {error && (
        <p className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-xs text-red-700 dark:bg-red-950/30 dark:text-red-200">{error}</p>
      )}
      {info && (
        <p className="mt-3 rounded-lg bg-blue-50 px-3 py-2 text-xs text-blue-700 dark:bg-blue-950/30 dark:text-blue-200">{info}</p>
      )}

      {ocrSummary && (
        <div className="mt-3 rounded-lg bg-zinc-50 px-3 py-2 text-xs text-zinc-700 dark:bg-zinc-800/70 dark:text-zinc-200">
          <p className="mb-1 font-semibold">Resumen OCR (español):</p>
          <pre className="whitespace-pre-wrap font-sans">{ocrSummary}</pre>
        </div>
      )}

      {/* Cancel */}
      <button
        type="button"
        onClick={() => {
          setCapturedImage(null)
          setMode(null)
          setError('')
          setInfo('')
          setOcrSummary('')
        }}
        className="mt-3 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm
                   text-slate-700 hover:bg-slate-50 dark:border-zinc-700 dark:bg-zinc-900/80 dark:text-zinc-200 dark:hover:bg-zinc-800"
      >
        Cancelar
      </button>
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import { supabase } from '../supabaseClient'
import AmountKeypadField from './AmountKeypadField'

const INITIAL_FORM = {
  item_name: '',
  estimated_price_krw: '',
}

// ── Componente con swipe ────────────────────────────────────────────────────
function SwipeableItem({ item, isChecking, onMoveToExpenses, onDelete }) {
  const [offsetX, setOffsetX] = useState(0)
  const [dragging, setDragging] = useState(false)
  const ptr = useRef({ startX: null, startY: null, captured: false })

  const THRESHOLD = 80
  const clamped = Math.max(-130, Math.min(130, offsetX))
  const rightPct = Math.min(1, Math.max(0, clamped / THRESHOLD))
  const leftPct  = Math.min(1, Math.max(0, -clamped / THRESHOLD))

  function onPointerDown(e) {
    if (e.pointerType === 'mouse' && e.button !== 0) return
    ptr.current = { startX: e.clientX, startY: e.clientY, captured: false }
  }

  function onPointerMove(e) {
    const { startX, startY, captured } = ptr.current
    if (startX === null) return

    const dx = e.clientX - startX
    const dy = e.clientY - startY

    if (!captured) {
      // Si el movimiento vertical gana → dejamos hacer scroll
      if (Math.abs(dy) > Math.abs(dx) + 5) {
        ptr.current.startX = null
        return
      }
      // Si el horizontal supera 8px → capturamos el puntero
      if (Math.abs(dx) > 8) {
        e.currentTarget.setPointerCapture(e.pointerId)
        ptr.current.captured = true
        setDragging(true)
      }
      return
    }

    setOffsetX(dx)
  }

  function onPointerUp(e) {
    const { startX, captured } = ptr.current
    ptr.current = { startX: null, startY: null, captured: false }
    setDragging(false)
    if (!captured || startX === null) return

    const dx = e.clientX - startX
    setOffsetX(0)

    if (dx > THRESHOLD)        onMoveToExpenses(item)
    else if (dx < -THRESHOLD)  onDelete(item.id)
  }

  function onPointerCancel() {
    ptr.current = { startX: null, startY: null, captured: false }
    setDragging(false)
    setOffsetX(0)
  }

  return (
    <li className="relative overflow-hidden rounded-xl border border-slate-200 dark:border-zinc-700">
      {/* Fondo derecha – mover a gastos */}
      <div
        className="pointer-events-none absolute inset-0 flex items-center gap-2 rounded-xl bg-emerald-500 px-5"
        style={{ opacity: rightPct }}
      >
        <span className="text-lg leading-none text-white">✓</span>
        <span className="text-sm font-bold text-white">A gastos</span>
      </div>

      {/* Fondo izquierda – eliminar */}
      <div
        className="pointer-events-none absolute inset-0 flex items-center justify-end gap-2 rounded-xl bg-red-500 px-5"
        style={{ opacity: leftPct }}
      >
        <span className="text-sm font-bold text-white">Eliminar</span>
        <span className="text-lg leading-none text-white">✕</span>
      </div>

      {/* Contenido deslizable */}
      <div
        className={`relative flex select-none flex-col gap-3 bg-white p-3 dark:bg-zinc-900/80 sm:flex-row sm:items-center${
          !dragging ? ' transition-transform duration-200 ease-out' : ''
        }`}
        style={{ transform: `translateX(${clamped}px)`, touchAction: 'pan-y' }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerCancel}
      >
        <button
          type="button"
          onClick={() => onMoveToExpenses(item)}
          disabled={isChecking}
          className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full border-2 border-slate-300 hover:border-emerald-500 disabled:opacity-50 dark:border-zinc-600"
          title="Tachar y mover a gastos"
        >
          {isChecking && (
            <span className="text-xs text-slate-400 dark:text-zinc-500">…</span>
          )}
        </button>

        <div className="min-w-0 flex-1">
          <p className="text-sm font-medium text-slate-900 dark:text-zinc-50">{item.item_name}</p>
          <p className="mt-0.5 text-xs text-slate-400 dark:text-zinc-500">
            {Number(item.estimated_price_krw).toLocaleString('es-ES')} KRW
          </p>
        </div>

        <button
          type="button"
          onClick={() => onDelete(item.id)}
          className="shrink-0 self-end text-lg text-slate-300 hover:text-red-500 dark:hover:text-red-400 sm:self-auto"
          title="Eliminar"
        >
          ×
        </button>
      </div>
    </li>
  )
}

// ── Componente principal ────────────────────────────────────────────────────
export default function ShoppingList() {
  const [items, setItems] = useState([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [checkingId, setCheckingId] = useState('')
  const [error, setError] = useState('')
  const [info, setInfo] = useState('')

  const [form, setForm] = useState(INITIAL_FORM)

  useEffect(() => {
    void fetchItems()
  }, [])

  async function fetchItems() {
    setLoading(true)
    const { data, error: e } = await supabase
      .from('shopping_list')
      .select('id, item_name, estimated_price_krw, created_at')
      .eq('is_purchased', false)
      .order('created_at', { ascending: false })

    if (e) {
      setError(e.message)
      setLoading(false)
      return
    }

    setItems(data ?? [])
    setLoading(false)
  }

  function handleChange(ev) {
    const { name, value } = ev.target
    setForm((prev) => ({ ...prev, [name]: value }))
  }

  async function handleSubmit(ev) {
    ev.preventDefault()
    setError('')
    setInfo('')

    if (!form.item_name.trim()) {
      setError('El nombre del producto es obligatorio.')
      return
    }

    if (!form.estimated_price_krw || Number(form.estimated_price_krw) <= 0) {
      setError('La cantidad estimada debe ser mayor que 0.')
      return
    }

    setSaving(true)

    const payload = {
      item_name: form.item_name.trim(),
      estimated_price_krw: Number(form.estimated_price_krw),
      is_purchased: false,
    }

    const { data, error: e } = await supabase
      .from('shopping_list')
      .insert(payload)
      .select('id, item_name, estimated_price_krw, created_at')
      .single()

    if (e) {
      setError(e.message)
      setSaving(false)
      return
    }

    setItems((prev) => [data, ...prev])
    setForm(INITIAL_FORM)
    setSaving(false)
  }

  async function handleCheckAndMove(item) {
    setError('')
    setInfo('')
    setCheckingId(item.id)

    const amount = Number(item.estimated_price_krw)
    if (!amount || amount <= 0) {
      setError('Ese producto no tiene una cantidad válida para mover a gastos.')
      setCheckingId('')
      return
    }

    const { error: expenseError } = await supabase.from('expenses').insert({
      expense_date: new Date().toISOString().slice(0, 10),
      category: 'Compras',
      amount_krw: amount,
      notes: item.item_name,
      status: 'pending',
    })

    if (expenseError) {
      setError(expenseError.message)
      setCheckingId('')
      return
    }

    const { error: updateError } = await supabase
      .from('shopping_list')
      .update({
        is_purchased: true,
        purchased_at: new Date().toISOString(),
      })
      .eq('id', item.id)

    if (updateError) {
      setError(updateError.message)
      setCheckingId('')
      return
    }

    setItems((prev) => prev.filter((row) => row.id !== item.id))
    setInfo(`"${item.item_name}" se movió a gastos.`)
    setCheckingId('')
  }

  async function handleDelete(id) {
    const { error: e } = await supabase.from('shopping_list').delete().eq('id', id)
    if (e) {
      setError(e.message)
      return
    }
    setItems((prev) => prev.filter((i) => i.id !== id))
  }

  return (
    <div className="space-y-4">
      <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700">
        <h2 className="mb-4 text-lg font-semibold text-slate-900 dark:text-zinc-50">️ Lista de compras</h2>
        <p className="mb-4 text-sm text-slate-500 dark:text-zinc-400">
          Apunta productos pendientes. Desliza{' '}
          <span className="font-medium text-emerald-600">→ derecha</span> para pasar a gastos o{' '}
          <span className="font-medium text-red-500">← izquierda</span> para eliminar.
        </p>

        <form onSubmit={handleSubmit} className="grid grid-cols-1 gap-3 sm:grid-cols-3">
          <label className="sm:col-span-2">
            <span className="mb-1 block text-sm text-slate-700 dark:text-zinc-200">Producto</span>
            <input
              type="text"
              name="item_name"
              value={form.item_name}
              onChange={handleChange}
              placeholder="Sunscreen Anessa, labial, etc."
              className="w-full rounded-xl border border-slate-300 px-3 py-2 dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-50"
              required
            />
          </label>

          <AmountKeypadField
            name="estimated_price_krw"
            label="Cantidad estimada (KRW)"
            value={form.estimated_price_krw}
            onChange={handleChange}
            placeholder="12.000"
          />

          <div className="sm:col-span-3">
            <button
              type="submit"
              disabled={saving}
              className="w-full rounded-xl bg-lavender-500 px-5 py-2 text-sm font-medium text-white hover:bg-lavender-600 disabled:opacity-50 sm:w-auto"
            >
              {saving ? 'Guardando…' : 'Agregar a la lista'}
            </button>
          </div>
        </form>

        {error && (
          <p className="mt-3 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700 dark:bg-red-950/40 dark:text-red-300">{error}</p>
        )}
        {info && (
          <p className="mt-3 rounded-lg bg-emerald-50 px-3 py-2 text-sm text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300">{info}</p>
        )}
      </div>

      <div className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200 dark:bg-zinc-900/80 dark:ring-zinc-700">
        {loading ? (
          <p className="text-sm text-slate-500 dark:text-zinc-400">Cargando lista…</p>
        ) : items.length === 0 ? (
          <p className="text-sm text-slate-500 dark:text-zinc-400">No tienes productos pendientes.</p>
        ) : (
          <ul className="space-y-2">
            {items.map((item) => (
              <SwipeableItem
                key={item.id}
                item={item}
                isChecking={checkingId === item.id}
                onMoveToExpenses={handleCheckAndMove}
                onDelete={handleDelete}
              />
            ))}
          </ul>
        )}

        {items.length > 0 && (
          <p className="mt-3 flex items-center justify-center gap-3 text-[11px] text-slate-300 dark:text-zinc-600">
            <span>← Eliminar</span>
            <span>·</span>
            <span>A gastos →</span>
          </p>
        )}
      </div>
    </div>
  )
}

